I haven't run this against a database, and the `orders` column names other than `id` and `created_at` are placeholders. It returns newest orders first.

```js
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool(); // reads PG* env vars
const router = express.Router();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function encodeCursor(row) {
  return Buffer.from(JSON.stringify([row.cursor_ts, row.id])).toString('base64url');
}

function decodeCursor(cursor) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
    if (typeof ts !== 'string' || Number.isNaN(Date.parse(ts))) return null;
    if (typeof id !== 'string' || !/^\d+$/.test(id)) return null;
    return { ts, id };
  } catch {
    return null;
  }
}

router.get('/orders', async (req, res, next) => {
  try {
    let limit = DEFAULT_LIMIT;
    if (req.query.limit !== undefined) {
      limit = Number(req.query.limit);
      if (!Number.isInteger(limit) || limit < 1) {
        return res.status(400).json({ error: 'limit must be a positive integer' });
      }
      limit = Math.min(limit, MAX_LIMIT);
    }

    const params = [limit + 1]; // fetch one extra row to detect a next page
    let where = '';
    if (req.query.cursor !== undefined) {
      const cursor = decodeCursor(String(req.query.cursor));
      if (!cursor) return res.status(400).json({ error: 'invalid cursor' });
      params.push(cursor.ts, cursor.id);
      where = 'WHERE (created_at, id) < ($2::timestamptz, $3::bigint)';
    }

    const { rows } = await pool.query(
      `SELECT id::text AS id, customer_id, status, total, created_at,
              to_char(created_at AT TIME ZONE 'UTC',
                      'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') AS cursor_ts
         FROM orders
         ${where}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      params
    );

    const hasMore = rows.length > limit;
    const page = hasMore ? rows.slice(0, limit) : rows;
    const nextCursor = hasMore ? encodeCursor(page[page.length - 1]) : null;

    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: nextCursor,
      has_more: hasMore,
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

It needs a matching index so each page is an index range scan:

```sql
CREATE INDEX orders_created_at_id_idx ON orders (created_at DESC, id DESC);
```

Clients call `GET /orders?limit=50`, then pass `next_cursor` back as `?cursor=...` until it comes back `null`.

- **Timestamp precision:** the cursor carries `created_at` as a microsecond-precision string produced by Postgres, not the JS `Date`. A `Date` truncates to milliseconds, which would make the comparison skip or repeat rows at page boundaries.
- **Schema assumptions:** `created_at` is `timestamptz` and `id` is a `bigint`/integer. If `id` is a UUID, change the `$3::bigint` cast to `$3::uuid`, and replace the digit check in `decodeCursor` with a UUID check.
- **Cursor trust:** the cursor is base64url-encoded JSON, validated but not signed. A client can craft one to start from any position, which is harmless here unless you later add per-user filtering that relies on the cursor.
